SELECT CASE WHEN stock_qty >= 408 THEN 'HIGH' ELSE 'LOW' END AS stock_qty_tier, APPROX_PERCENTILE(stock_qty, ARRAY(0.25, 0.5, 0.75)) AS stock_qty_quartiles, ROUND(AVG(cost), 2) AS avg_cost, ROUND(AVG(cost), 2) AS avg_cost_2, ROUND(SUM(stock_qty) / NULLIF(COUNT(CASE WHEN category = 'Grocery' THEN 1 END), 0), 2) AS stock_qty_per_grocery, COUNT(DISTINCT supplier_id) AS distinct_supplier_ids FROM products GROUP BY CUBE (CASE WHEN stock_qty >= 408 THEN 'HIGH' ELSE 'LOW' END);
